wave-field:
import { Buffer, elementKernel } from 'wgpu-kit';

const color = await Buffer.create('vec4f', size * size);
const waves = elementKernel({
  state: { color: 'vec4f' },
  uniforms: { size: 'u32', time: 'f32', pointer: 'vec2f', gain: 'f32' },
  code: `
    fn userFn(idx: u32, size: u32, time: f32, pointer: vec2f, gain: f32) {
      let uv = vec2f(f32(idx % size), f32(idx / size)) / f32(size);
      let p = (uv - 0.5) * 2.0;
      let a = sin(length(p - vec2f(-0.55, -0.2)) * 27.0 - time * 2.5);
      let b = sin(length(p - vec2f(0.45, 0.3)) * 30.0 - time * 2.0);
      let c = sin(length(p - pointer) * 32.0 - time * 3.0);
      let signal = (a + b + c) / 3.0;
      let ridge = pow(max(0.0, signal), 3.0);
      let phase = 0.5 + 0.5 * signal;
      let tint = 0.5 + 0.5 * cos(6.28318 * (phase * 0.55 + vec3f(0.12, 0.38, 0.68)));
      let vignette = (1.0 - smoothstep(0.25, 1.45, length(p)));
      color[idx] =
        vec4f(
          (tint * (0.06 + ridge * gain * 1.8) + vec3f(ridge * 0.2)) * vignette,
          1.0,
        );
    }
  `,
});
await waves.run({ color }, { size, time, pointer: { x: 0, y: 0 }, gain: 1.0 });

reaction-diffusion:
import { PingPong, elementKernel } from 'wgpu-kit';

const state = await PingPong.create({ chem: 'vec2f' }, size * size);
const step = elementKernel({
  state: { chemicals: 'vec2f' },
  inputs: { previous: 'vec2f' },
  uniforms: { size: 'u32', feed: 'f32', kill: 'f32', pointer: 'vec2f', press: 'f32' },
  code: `
    fn sampleAt(x: i32, y: i32, size: u32) -> vec2f {
      let n = i32(size);
      let xx = (x + n) % n;
      let yy = (y + n) % n;
      return previous[u32(yy * n + xx)];
    }

    fn userFn(idx: u32, size: u32, feed: f32, kill: f32, pointer: vec2f, press: f32) {
      let x = i32(idx % size);
      let y = i32(idx / size);
      let ab = previous[idx];
      var lap = -ab;
      lap +=
        0.2 * (sampleAt(x - 1, y, size)
          + sampleAt(x + 1, y, size)
          + sampleAt(x, y - 1, size)
          + sampleAt(x, y + 1, size));
      lap +=
        0.05 * (sampleAt(x - 1, y - 1, size)
          + sampleAt(x + 1, y - 1, size)
          + sampleAt(x - 1, y + 1, size)
          + sampleAt(x + 1, y + 1, size));
      let reaction = ab.x * ab.y * ab.y;
      var next =
        ab + vec2f(
          lap.x - reaction + feed * (1.0 - ab.x),
          0.5 * lap.y + reaction - (kill + feed) * ab.y,
        );
      let uv = vec2f(f32(x), f32(y)) / f32(size);
      if (press > 0.5 && distance(uv, pointer) < 0.04) {
        next = vec2f(0.4, 0.85);
      }
      chemicals[idx] = clamp(next, vec2f(0.0), vec2f(1.0));
    }
  `,
});
await step.run(
  { chemicals: state.other.chem, previous: state.current.chem },
  { size, feed: 0.0367, kill: 0.0649, pointer: { x: 0.5, y: 0.5 }, press: 0 },
);
state.swap();

image-convolution:
import { Buffer, elementKernel } from 'wgpu-kit';

const original = await Buffer.create('vec4f', size * size);
const color = await Buffer.create('vec4f', size * size);
original.write(imagePixels);
const filter = elementKernel({
  state: { color: 'vec4f' },
  inputs: { original: 'vec4f' },
  uniforms: { size: 'u32', mode: 'u32', split: 'f32', strength: 'f32' },
  code: `
    fn sampleAt(x: i32, y: i32, size: u32) -> vec3f {
      let n = i32(size);
      let xx = clamp(x, 0, n - 1);
      let yy = clamp(y, 0, n - 1);
      return original[u32(yy * n + xx)].xyz;
    }

    fn userFn(idx: u32, size: u32, mode: u32, split: f32, strength: f32) {
      let x = i32(idx % size);
      let y = i32(idx / size);
      let center = original[idx].xyz;
      var result = center;
      if (mode == 1u) {
        let gx =
          -sampleAt(x - 1, y - 1, size)
            - 2.0 * sampleAt(x - 1, y, size)
            - sampleAt(x - 1, y + 1, size)
            + sampleAt(x + 1, y - 1, size)
            + 2.0 * sampleAt(x + 1, y, size)
            + sampleAt(x + 1, y + 1, size);
        let gy =
          -sampleAt(x - 1, y - 1, size)
            - 2.0 * sampleAt(x, y - 1, size)
            - sampleAt(x + 1, y - 1, size)
            + sampleAt(x - 1, y + 1, size)
            + 2.0 * sampleAt(x, y + 1, size)
            + sampleAt(x + 1, y + 1, size);
        let edge = length(gx) + length(gy);
        result = vec3f(0.3, 0.78, 1.0) * edge * strength;
      } else if (mode == 2u) {
        result = vec3f(0.0);
        for (var yy = -1; yy <= 1; yy++) {
          for (var xx = -1; xx <= 1; xx++) {
            let weight = select(1.0, 2.0, xx == 0) * select(1.0, 2.0, yy == 0);
            result += sampleAt(x + xx * 3, y + yy * 3, size) * weight / 16.0;
          }
        }
      } else if (mode == 3u) {
        let neighbors =
          sampleAt(x - 1, y, size)
            + sampleAt(x + 1, y, size)
            + sampleAt(x, y - 1, size)
            + sampleAt(x, y + 1, size);
        result = center + (4.0 * center - neighbors) * strength;
      }
      if (f32(x) / f32(size) < split) {
        result = center;
      }
      if (abs(f32(x) / f32(size) - split) < 0.003) {
        result = vec3f(0.9);
      }
      color[idx] = vec4f(clamp(result, vec3f(0.0), vec3f(1.0)), 1.0);
    }
  `,
});
await filter.run({ color, original }, { size, mode: 1, split: 0.5, strength: 1 });

prefix-sum:
import { Buffer, createScan, createReduce } from 'wgpu-kit';

const data = new Uint32Array([3, 1, 4, 1, 5, 9, 2, 6]);
const input = await Buffer.create('u32', data.length);
const output = await Buffer.create('u32', data.length);
input.write(data);
const scan = createScan();
await scan.run(input, output, data.length, true);
const prefix = await output.read();
const reduce = createReduce();
const sum = await reduce.sum(input, data.length);
// prefix: [0, 3, 4, 8, 9, 14, 23, 25]; sum: 31
scan.destroy();
reduce.destroy();
input.destroy();
output.destroy();

volumetric-nebula:
import { Buffer, elementKernel } from 'wgpu-kit';

const color = await Buffer.create('vec4f', size * size);
const shader = elementKernel({
  state: { color: 'vec4f' },
  uniforms: {
    size: 'u32',
    time: 'f32',
    pointer: 'vec2f',
    amount: 'f32',
    aspect: 'f32',
    light: 'f32',
  },
  code: `
    fn hash(p: vec2f) -> f32 {
      return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453);
    }

    fn noise(p: vec2f) -> f32 {
      let i = floor(p);
      let f = fract(p);
      let u = f * f * (3.0 - 2.0 * f);
      return
        mix(
          mix(hash(i), hash(i + vec2f(1, 0)), u.x),
          mix(hash(i + vec2f(0, 1)), hash(i + vec2f(1, 1)), u.x),
          u.y,
        );
    }

    fn fbm(p0: vec2f) -> f32 {
      var p = p0;
      var s = 0.0;
      var a = 0.5;
      for (var j = 0; j < 5; j++) {
        s += a * noise(p);
        p = mat2x2f(1.62, 1.17, -1.17, 1.62) * p + 3.71;
        a *= 0.5;
      }
      return s;
    }

    fn palette(t: f32) -> vec3f {
      return 0.5 + 0.5 * cos(6.283185 * (vec3f(.1, .35, .6) + t));
    }

    fn stars(p: vec2f) -> vec3f {
      let q = p * 130.0;
      let cell = floor(q);
      let f = fract(q) - 0.5;
      let h = hash(cell);
      let r = length(f - vec2f(hash(cell + 1.7), hash(cell + 8.2)) * .35);
      let b = pow(max(0.0, 1.0 - r * 8.0), 6.0) * step(.965, h);
      return mix(vec3f(.55, .7, 1), vec3f(1, .72, .4), hash(cell + 4.1)) * b * 2.5;
    }

    fn userFn(
      idx: u32,
      size: u32,
      time: f32,
      pointer: vec2f,
      amount: f32,
      aspect: f32,
      light: f32,
    ) {
      let uv = (vec2f(f32(idx % size), f32(idx / size)) + .5) / f32(size);
      let p = (uv - .5) * vec2f(2.0 * aspect, 2.0);
      var rgb = vec3f(0);
      var trans = 1.0;
      var col = vec3f(0);
      for (var k = 0; k < 28; k++) {
        let z = f32(k) * .13;
        let q = p * 1.3 + pointer * .22 + vec2f(z * .18, sin(z + time * .1) * .22);
        let n = fbm(q * 2.2 + vec2f(z * .8, time * .035));
        let d = max(0.0, n - .40) * amount * .23;
        let light =
          mix(vec3f(.22, .075, .65), vec3f(.04, .75, .8), clamp(z / 3.6, 0.0, 1.0));
        col += trans * d * light * 2.6;
        trans *= exp(-d * 1.5);
      }
      rgb = col + stars(p) * trans;
      if (light > .5) {
        rgb = mix(vec3f(.88, .91, .94), rgb, .76);
      }
      color[idx] = vec4f(clamp(rgb, vec3f(0), vec3f(1)), 1);
    }
  `,
});
await shader.run(
  { color },
  { size, time: 0, pointer: { x: 0, y: 0 }, amount: 1, aspect: 1.5, light: 0 },
);
