mandelbulb:
import { Buffer, elementKernel } from 'wgpu-kit';

const color = await Buffer.create('vec4f', size * size);
const shader = elementKernel({
  state: { color: 'vec4f' },
  uniforms: {
    size: 'u32',
    time: 'f32',
    pointer: 'vec2f',
    amount: 'f32',
    aspect: 'f32',
    light: 'f32',
  },
  code: `
    fn hash(p: vec2f) -> f32 {
      return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453);
    }

    fn noise(p: vec2f) -> f32 {
      let i = floor(p);
      let f = fract(p);
      let u = f * f * (3.0 - 2.0 * f);
      return
        mix(
          mix(hash(i), hash(i + vec2f(1, 0)), u.x),
          mix(hash(i + vec2f(0, 1)), hash(i + vec2f(1, 1)), u.x),
          u.y,
        );
    }

    fn fbm(p0: vec2f) -> f32 {
      var p = p0;
      var s = 0.0;
      var a = 0.5;
      for (var j = 0; j < 5; j++) {
        s += a * noise(p);
        p = mat2x2f(1.62, 1.17, -1.17, 1.62) * p + 3.71;
        a *= 0.5;
      }
      return s;
    }

    fn palette(t: f32) -> vec3f {
      return 0.5 + 0.5 * cos(6.283185 * (vec3f(.1, .35, .6) + t));
    }

    fn stars(p: vec2f) -> vec3f {
      let q = p * 130.0;
      let cell = floor(q);
      let f = fract(q) - 0.5;
      let h = hash(cell);
      let r = length(f - vec2f(hash(cell + 1.7), hash(cell + 8.2)) * .35);
      let b = pow(max(0.0, 1.0 - r * 8.0), 6.0) * step(.965, h);
      return mix(vec3f(.55, .7, 1), vec3f(1, .72, .4), hash(cell + 4.1)) * b * 2.5;
    }

    fn bulb(p: vec3f, power: f32) -> f32 {
      var z = p;
      var dr = 1.0;
      var r = 0.0;
      for (var j = 0; j < 8; j++) {
        r = length(z);
        if (r > 2.0) {
          break;
        }
        let safe = max(r, .0001);
        let theta = acos(clamp(z.z / safe, -1.0, 1.0));
        let phi = atan2(z.y, z.x);
        dr = pow(safe, power - 1.0) * power * dr + 1.0;
        let zr = pow(safe, power);
        z =
          zr * vec3f(
            sin(theta * power) * cos(phi * power),
            sin(theta * power) * sin(phi * power),
            cos(theta * power),
          ) + p;
      }
      return .5 * log(max(r, 1.001)) * r / dr;
    }

    fn userFn(
      idx: u32,
      size: u32,
      time: f32,
      pointer: vec2f,
      amount: f32,
      aspect: f32,
      light: f32,
    ) {
      let uv = (vec2f(f32(idx % size), f32(idx / size)) + .5) / f32(size);
      let p = (uv - .5) * vec2f(2.0 * aspect, 2.0);
      var rgb = vec3f(0);
      let yaw = time * .12 + pointer.x * 1.8;
      let ro = vec3f(sin(yaw) * 2.65, .35 + pointer.y * .6, cos(yaw) * 2.65);
      let ww = normalize(-ro);
      let uu = normalize(cross(ww, vec3f(0, 1, 0)));
      let vv = cross(uu, ww);
      let rd = normalize(ww + p.x * uu - p.y * vv);
      var t = 0.0;
      var hit = false;
      var pos = ro;
      var steps = 0.0;
      for (var k = 0; k < 64; k++) {
        pos = ro + rd * t;
        let d = bulb(pos, amount);
        if (d < .003) {
          hit = true;
          break;
        }
        t += max(d, .002);
        steps = f32(k);
        if (t > 7.0) {
          break;
        }
      }
      rgb = vec3f(.008, .012, .025) + vec3f(.025, .04, .07) * max(0.0, 1.0 - length(p));
      if (hit) {
        let e = .004;
        let n =
          normalize(
            vec3f(
              bulb(pos + vec3f(e, 0, 0), amount) - bulb(pos - vec3f(e, 0, 0), amount),
              bulb(pos + vec3f(0, e, 0), amount) - bulb(pos - vec3f(0, e, 0), amount),
              bulb(pos + vec3f(0, 0, e), amount) - bulb(pos - vec3f(0, 0, e), amount),
            ),
          );
        let lit = max(0.0, dot(n, normalize(vec3f(-.6, 1, 1))));
        rgb =
          mix(
            vec3f(.24, .48, .62),
            vec3f(.94, .63, .3),
            clamp(length(pos) * .7, 0.0, 1.0),
          )
            * (.3 + lit * .9)
            * (1.0 - steps / 100.0) + pow(
            max(0.0, dot(reflect(rd, n), normalize(vec3f(-.6, 1, 1)))),
            16.0,
          ) * .5;
      }
      if (light > .5) {
        rgb = mix(vec3f(.88, .91, .94), rgb, .76);
      }
      color[idx] = vec4f(clamp(rgb, vec3f(0), vec3f(1)), 1);
    }
  `,
});
await shader.run(
  { color },
  { size, time: 0, pointer: { x: 0, y: 0 }, amount: 8, aspect: 1.5, light: 0 },
);
// The complete module includes a native WebGPU render pass.
