import { Buffer, elementKernel } from 'wgpu-kit';

const color = await Buffer.create('vec4f', size * size);
const shader = elementKernel({
  state: { color: 'vec4f' },
  uniforms: {
    size: 'u32',
    time: 'f32',
    pointer: 'vec2f',
    amount: 'f32',
    aspect: 'f32',
    light: 'f32',
  },
  code: `
    fn hash(p: vec2f) -> f32 {
      return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453);
    }

    fn noise(p: vec2f) -> f32 {
      let i = floor(p);
      let f = fract(p);
      let u = f * f * (3.0 - 2.0 * f);
      return
        mix(
          mix(hash(i), hash(i + vec2f(1, 0)), u.x),
          mix(hash(i + vec2f(0, 1)), hash(i + vec2f(1, 1)), u.x),
          u.y,
        );
    }

    fn fbm(p0: vec2f) -> f32 {
      var p = p0;
      var s = 0.0;
      var a = 0.5;
      for (var j = 0; j < 5; j++) {
        s += a * noise(p);
        p = mat2x2f(1.62, 1.17, -1.17, 1.62) * p + 3.71;
        a *= 0.5;
      }
      return s;
    }

    fn palette(t: f32) -> vec3f {
      return 0.5 + 0.5 * cos(6.283185 * (vec3f(.1, .35, .6) + t));
    }

    fn stars(p: vec2f) -> vec3f {
      let q = p * 130.0;
      let cell = floor(q);
      let f = fract(q) - 0.5;
      let h = hash(cell);
      let r = length(f - vec2f(hash(cell + 1.7), hash(cell + 8.2)) * .35);
      let b = pow(max(0.0, 1.0 - r * 8.0), 6.0) * step(.965, h);
      return mix(vec3f(.55, .7, 1), vec3f(1, .72, .4), hash(cell + 4.1)) * b * 2.5;
    }

    fn cmul(a: vec2f, b: vec2f) -> vec2f {
      return vec2f(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x);
    }

    fn cdiv(a: vec2f, b: vec2f) -> vec2f {
      return vec2f(dot(a, b), a.y * b.x - a.x * b.y) / max(dot(b, b), .00001);
    }

    fn userFn(
      idx: u32,
      size: u32,
      time: f32,
      pointer: vec2f,
      amount: f32,
      aspect: f32,
      light: f32,
    ) {
      let uv = (vec2f(f32(idx % size), f32(idx / size)) + .5) / f32(size);
      let p = (uv - .5) * vec2f(2.0 * aspect, 2.0);
      var rgb = vec3f(0);
      var z = p * 2.0 / max(.3, amount) + pointer * .5;
      var iterations = 0.0;
      for (var k = 0; k < 36; k++) {
        let z2 = cmul(z, z);
        let f = cmul(z2, z) - vec2f(1, 0);
        let d = z2 * 3.0;
        z -= cdiv(f, d);
        iterations = f32(k);
        if (length(f) < .0001) {
