      let r = length(f - vec2f(hash(cell + 1.7), hash(cell + 8.2)) * .35);
      let b = pow(max(0.0, 1.0 - r * 8.0), 6.0) * step(.965, h);
      return mix(vec3f(.55, .7, 1), vec3f(1, .72, .4), hash(cell + 4.1)) * b * 2.5;
    }

    fn terrain(p: vec2f, a: f32) -> f32 {
      return (fbm(p * 1.05) - .23) * a * .9;
    }

    fn userFn(
      idx: u32,
      size: u32,
      time: f32,
      pointer: vec2f,
      amount: f32,
      aspect: f32,
      light: f32,
    ) {
      let uv = (vec2f(f32(idx % size), f32(idx / size)) + .5) / f32(size);
      let p = (uv - .5) * vec2f(2.0 * aspect, 2.0);
      var rgb = vec3f(0);
      let yaw = pointer.x * 1.8 + time * .045;
      let ro = vec3f(sin(yaw) * 3.0, 2.0, cos(yaw) * 3.0);
      let lookAt = vec3f(0, .2, 0);
      let ww = normalize(lookAt - ro);
      let uu = normalize(cross(ww, vec3f(0, 1, 0)));
      let vv = cross(uu, ww);
      let rd = normalize(ww + p.x * uu - p.y * vv);
      var travel = 0.0;
      var hit = false;
      var pos = ro;
      for (var k = 0; k < 72; k++) {
        pos = ro + rd * travel;
        let d = pos.y - terrain(pos.xz, amount);
