magnetic-tide:
import { PingPong, elementKernel } from 'wgpu-kit';

// A persistent height field follows a localized magnetic target.
const size = 160;
const field = await PingPong.create({ height: 'f32' }, size * size);
const sculpt = elementKernel({
  state: { next: 'f32' },
  inputs: { previous: 'f32' },
  uniforms: { size: 'u32', hand: 'vec2f', strength: 'f32', press: 'f32', dt: 'f32' },
  code: `
    fn userFn(i: u32, size: u32, hand: vec2f, strength: f32, press: f32, dt: f32) {
      let uv = vec2f(f32(i % size), f32(i / size)) / f32(size - 1u);
      let p = (uv - 0.5) * 2.6;
      let rim = 1.0 - smoothstep(1.10, 1.20, length(p));
      let q = p - hand;
      let envelope = exp(-dot(q, q) * 2.4);
      let a = cos(p.x * 23.0);
      let b = cos(dot(p, vec2f(11.5, 19.9186)));
      let c = cos(dot(p, vec2f(-11.5, 19.9186)));
      let hex = pow(max(0.0, (a + b + c) / 3.0), 2.1);
      let desired =
        rim * (0.018 + strength * envelope * (0.05 + hex * (0.48 + press * 0.32)));
      next[i] = mix(previous[i], desired, 1.0 - exp(-dt * 8.0));
    }
  `,
});
await sculpt.prepare();

// Submit one step, then render directly from field.current.height.gpuBuffer.
await sculpt.run(
  { next: field.other.height, previous: field.current.height },
  {
    size,
    hand: { x: 0, y: 0 },
    strength: 1,
    press: 0,
    dt: 1 / 60,
  },
);
field.swap();

