    movement: 'vec2f',
    press: 'f32',
    strength: 'f32',
  },
  code: `
    fn at(p: vec2f, size: u32) -> vec2f {
      let xy = clamp(p, vec2f(0), vec2f(f32(size) - 1.001));
      let a = vec2u(xy);
      let f = fract(xy);
      return
        mix(
          mix(previous[a.y * size + a.x].xy, previous[a.y * size + a.x + 1u].xy, f.x),
          mix(
            previous[(a.y + 1u) * size + a.x].xy,
            previous[(a.y + 1u) * size + a.x + 1u].xy,
            f.x,
          ),
          f.y,
        );
    }

    fn userFn(
      i: u32,
      size: u32,
      dt: f32,
      hand: vec2f,
      movement: vec2f,
      press: f32,
      strength: f32,
    ) {
      let xy = vec2f(f32(i % size), f32(i / size));
      let uv = (xy + 0.5) / f32(size);
      let v = previous[i].xy;
      let back = xy - v * dt * f32(size);
      let weight = exp(-dot(uv - hand, uv - hand) * 1600.0) * press;
      let force = movement * weight * strength * 24.0;
      var value = at(back, size) * 0.992 + force;
      let speed = length(value);
      if (speed > 1.5) {
        value *= 1.5 / speed;
      }
      if (i % size < 2u || i % size > size - 3u) {
        value.x = 0.0;
      }
      if (i / size < 2u || i / size > size - 3u) {
        value.y = 0.0;
      }
      next[i] = vec4f(value, 0, 0);
    }
  `,
});

// 2. Measure local expansion and compression in the velocity field.
const measure = elementKernel({
  state: { divergence: 'f32' },
  inputs: { velocity: 'vec4f' },
  uniforms: { size: 'u32' },
  code: `
    fn at(x: i32, y: i32, size: u32) -> vec2f {
      return
        velocity[u32(clamp(y, 0, i32(size) - 1)) * size + u32(
          clamp(x, 0, i32(size) - 1),
        )].xy;
    }

    fn userFn(i: u32, size: u32) {
      let x = i32(i % size);
      let y = i32(i / size);
      divergence[i] =
        (at(x + 1, y, size).x
          - at(x - 1, y, size).x
          + at(x, y + 1, size).y
          - at(x, y - 1, size).y)
          * 0.5
          * f32(size);
    }
  `,
});

// 3. Solve pressure with 20 Jacobi iterations.
// Distinct instances respect elementKernel's one-encode-per-submit constraint.
const pressureSteps = Array.from({ length: 20 }, () =>
  elementKernel({
    state: { next: 'f32' },
    inputs: { previous: 'f32', divergence: 'f32' },
    uniforms: { size: 'u32' },
    code: `
    fn at(x: i32, y: i32, size: u32) -> f32 {
      return
        previous[u32(clamp(y, 0, i32(size) - 1)) * size + u32(
          clamp(x, 0, i32(size) - 1),
        )];
    }

    fn userFn(i: u32, size: u32) {
      let x = i32(i % size);
      let y = i32(i / size);
      next[i] =
        (at(x - 1, y, size)
          + at(x + 1, y, size)
          + at(x, y - 1, size)
          + at(x, y + 1, size)
          - divergence[i] / f32(size * size)) * 0.25;
    }
  `,
  }),
);

// 4. Remove the pressure gradient to approximate incompressible flow.
const project = elementKernel({
  state: { next: 'vec4f' },
  inputs: { velocity: 'vec4f', pressure: 'f32' },
  uniforms: { size: 'u32' },
  code: `
    fn at(x: i32, y: i32, size: u32) -> f32 {
      return
        pressure[u32(clamp(y, 0, i32(size) - 1)) * size + u32(
          clamp(x, 0, i32(size) - 1),
        )];
    }

    fn userFn(i: u32, size: u32) {
      let x = i32(i % size);
      let y = i32(i / size);
      let gradient =
        vec2f(
          at(x + 1, y, size) - at(x - 1, y, size),
          at(x, y + 1, size) - at(x, y - 1, size),
        )
          * 0.5
          * f32(size);
      next[i] = vec4f(velocity[i].xy - gradient, 0, 0);
    }
  `,
});

// 5. Advect the finer pigment grid with that projected velocity.
// rawKernel permits different buffer lengths and explicit bindings.
const transport = rawKernel(`
    struct Params {
      sizes: vec4u,
      brush: vec4f,
      step: vec4f,
    }

    @group(0) @binding(0) var<storage, read> previous: array<vec4f>;
    @group(0) @binding(1) var<storage, read> velocity: array<vec4f>;
    @group(0) @binding(2) var<storage, read_write> next: array<vec4f>;
    @group(0) @binding(3) var<uniform> params: Params;

    fn flow(uv: vec2f) -> vec2f {
      let n = params.sizes.y;
      let p = clamp(uv * f32(n) - 0.5, vec2f(0), vec2f(f32(n) - 1.001));
      let a = vec2u(p);
      let f = fract(p);
      return
        mix(
          mix(velocity[a.y * n + a.x].xy, velocity[a.y * n + a.x + 1u].xy, f.x),
          mix(
            velocity[(a.y + 1u) * n + a.x].xy,
            velocity[(a.y + 1u) * n + a.x + 1u].xy,
            f.x,
          ),
          f.y,
        );
    }

    fn pigment(uv: vec2f) -> vec4f {
      let n = params.sizes.x;
      let p = clamp(uv * f32(n) - 0.5, vec2f(0), vec2f(f32(n) - 1.001));
      let a = vec2u(p);
      let f = fract(p);
      return
        mix(
          mix(previous[a.y * n + a.x], previous[a.y * n + a.x + 1u], f.x),
          mix(previous[(a.y + 1u) * n + a.x], previous[(a.y + 1u) * n + a.x + 1u], f.x),
          f.y,
        );
    }

    @compute @workgroup_size(64)
    fn main(@builtin(global_invocation_id) id: vec3u) {
      let n = params.sizes.x;
      let i = id.x;
      if (i >= n * n) {
        return;
      }
      let uv = (vec2f(f32(i % n), f32(i / n)) + 0.5) / f32(n);
      var color = pigment(uv - flow(uv) * params.step.x);
      let q = uv - params.brush.xy;
      let brush = exp(-dot(q, q) * 3200.0) * params.brush.z;
      let cream = vec3f(0.95, 0.92, 0.83);
      let phase = u32(params.step.y * 0.4) % 3u;
      let colors =
        array<vec3f, 3>(
          vec3f(0.035, 0.105, 0.20),
          vec3f(0.72, 0.18, 0.105),
          vec3f(0.75, 0.48, 0.15),
        );
      if (params.brush.w > 0.5) {
        let ink = select(colors[phase], cream, params.brush.w > 1.5);
        color = vec4f(mix(color.rgb, ink, brush * 0.5), 1);
      }
      next[i] = clamp(color, vec4f(0), vec4f(1));
    }
  `);
await Promise.all([
  advect.prepare(),
  measure.prepare(),
  project.prepare(),
  transport.prepare(),
  ...pressureSteps.map((step) => step.prepare()),
]);

// Each frame uses one command encoder and no simulation readback.
// Seed both pigment buffers before the first frame; the live study uses
// indigo, vermilion, gold and ivory bands as its initial condition.
function encodeFlow(
  encoder: GPUCommandEncoder,
  dt: number,
  hand: { x: number; y: number },
  movement: { x: number; y: number },
  pressed: boolean,
  strength: number,
  parameters: GPUBuffer,
) {
  advect.encode(
    encoder,
    {
      next: velocity.other.flow,
      previous: velocity.current.flow,
    },
    { size, dt, hand, movement, press: pressed ? 1 : 0, strength },
  );
  velocity.swap();

  measure.encode(encoder, { divergence, velocity: velocity.current.flow }, { size });
  for (const solve of pressureSteps) {
    solve.encode(
      encoder,
      {
        next: pressure.other.value,
        previous: pressure.current.value,
        divergence,
      },
      { size },
    );
    pressure.swap();
  }

  project.encode(
    encoder,
    {
      next: velocity.other.flow,
      velocity: velocity.current.flow,
      pressure: pressure.current.value,
    },
    { size },
  );
  velocity.swap();

  transport.encode(
    encoder,
    [
      { binding: 0, resource: { buffer: pigment.current.color.gpuBuffer } },
      { binding: 1, resource: { buffer: velocity.current.flow.gpuBuffer } },
      { binding: 2, resource: { buffer: pigment.other.color.gpuBuffer } },
      { binding: 3, resource: { buffer: parameters } },
    ],
    Math.ceil((pigmentSize * pigmentSize) / 64),
  );
  pigment.swap();
}
// After queue.submit(), call endSubmit() on every encoded elementKernel.
// Download materials.ts for parameter packing, rendering, input and cleanup.

bend-light:
import { Buffer, elementKernel, rawKernel } from 'wgpu-kit';

// Height + slope field used by the ray pass and glass renderer.
const surface = await Buffer.create('vec4f', size * size);
const shape = elementKernel({
  state: { surface: 'vec4f' },
  uniforms: { size: 'u32', hand: 'vec2f', bend: 'f32' },
  code: `
    fn userFn(i: u32, size: u32, hand: vec2f, bend: f32) {
      let p = (vec2f(f32(i % size), f32(i / size)) / f32(size - 1u) - .5) * 1.8;
      let q = p - hand;
      let g = exp(-dot(q, q) * 3.2);
      let wave = sin(p.x * 2.5 + p.y * 1.2);
      let h =
        .24 + bend * (.16 * g
          + .065 * sin(p.x * 5.0 + p.y * 1.5)
          + .035 * cos(p.y * 6.0));
      let dx = bend * (-1.024 * q.x * g + .325 * cos(p.x * 5.0 + p.y * 1.5));
      let dz =
        bend * (-1.024 * q.y * g
          + .0975 * cos(p.x * 5.0 + p.y * 1.5)
          - .21 * sin(p.y * 6.0));
      surface[i] = vec4f(h, dx, dz, 1);
    }
  `,
});

// Atomic accumulation requires raw WGSL bindings.
const rays = rawKernel(`
    struct Params {
      size: u32,
      rays: u32,
      frame: u32,
      pad: u32,
    }

    @group(0) @binding(0) var<storage, read> surface: array<vec4f>;
    @group(0) @binding(1) var<storage, read_write> energy: array<atomic<u32>>;
    @group(0) @binding(2) var<uniform> params: Params;

    fn sampleAt(uv: vec2f) -> vec4f {
      let p = clamp(uv, vec2f(0), vec2f(.999)) * f32(params.size - 1u);
      let xy = vec2u(p);
      let f = fract(p);
      let x1 = min(xy.x + 1u, params.size - 1u);
      let y1 = min(xy.y + 1u, params.size - 1u);
      return
        mix(
          mix(
            surface[xy.y * params.size + xy.x],
            surface[xy.y * params.size + x1],
            f.x,
          ),
          mix(surface[y1 * params.size + xy.x], surface[y1 * params.size + x1], f.x),
          f.y,
        );
    }

    @compute @workgroup_size(64)
    fn main(@builtin(global_invocation_id) id: vec3u) {
      let count = params.rays * params.rays;
      if (id.x >= count) {
        return;
      }
      let uv =
        (vec2f(f32(id.x % params.rays), f32(id.x / params.rays)) + .5) / f32(
          params.rays,
        );
      let s = sampleAt(uv);
      let p = (uv - .5) * 1.8;
      let entry = vec3f(p.x, 1.05 + s.x, p.y);
      let n = normalize(vec3f(-s.y, 1, -s.z));
      let incoming = normalize(vec3f(.09, -1, .04));
      for (var c = 0u; c < 3u; c++) {
        let ior = 1.40 + f32(c) * .055;
        let inside = refract(incoming, n, 1.0 / ior);
        let base = entry + inside * ((1.05 - entry.y) / min(-.01, inside.y));
        let outgoing = refract(inside, vec3f(0, 1, 0), ior);
        if (length(outgoing) < .1) {
          continue;
        }
        let hit = base + outgoing * (-base.y / min(-.01, outgoing.y));
        let coord = vec2i((hit.xz / 3.0 + .5) * f32(params.size));
        if (any(coord < vec2i(0)) || any(coord >= vec2i(i32(params.size)))) {
          continue;
        }
        let index = u32(coord.y) * params.size + u32(coord.x);
        atomicAdd(&energy[index * 4u + c], 1024u);
      }
    }
  `);
await Promise.all([shape.prepare(), rays.prepare()]);
// Download tactile.ts for exact binding, submission, rendering and cleanup.

frost-glass:
import { PingPong, elementKernel } from 'wgpu-kit';

const state = await PingPong.create({ crystal: 'vec4f' }, size * size);
// Four distinct kernel instances compose four substeps in one encoder.
const steps = Array.from({ length: 4 }, () =>
  elementKernel({
    state: { next: 'vec4f' },
    inputs: { previous: 'vec4f' },
    uniforms: { size: 'u32', hand: 'vec2f', press: 'f32', tool: 'f32', cold: 'f32' },
    code: `
    fn hash(p: vec2f) -> f32 {
      return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453);
    }

    fn readAt(x: i32, y: i32, size: u32) -> vec4f {
      let n = i32(size);
      return previous[u32(clamp(y, 0, n - 1) * n + clamp(x, 0, n - 1))];
    }

    fn userFn(i: u32, size: u32, hand: vec2f, press: f32, tool: f32, cold: f32) {
      let x = i32(i % size);
      let y = i32(i / size);
      let s = previous[i];
      let parity = y % 2;
      var vapor = 0.0;
      var heat = 0.0;
      var frontier = 0.0;
      var dirs =
        array<vec2i, 6>(
          vec2i(-1, 0),
          vec2i(1, 0),
          vec2i(parity - 1, -1),
          vec2i(parity, -1),
          vec2i(parity - 1, 1),
          vec2i(parity, 1),
        );
      for (var k = 0; k < 6; k++) {
        let a = readAt(x + dirs[k].x, y + dirs[k].y, size);
        vapor += a.y / 6.0;
        heat += a.z / 6.0;
        frontier = max(frontier, step(.999, a.x));
      }
      let uv = vec2f(f32(x), f32(y)) / f32(size);
      let p = (uv - .5) * 2.0;
      let angle = atan2(p.y, p.x);
      let anisotropy = .42 + .58 * pow(.5 + .5 * cos(angle * 6.0), 3.0);
      var mass = s.x;
      var v = max(0.0, s.y + (vapor - s.y) * .36);
      var temperature = s.z + (heat - s.z) * .20 - s.z * .017;
      let receptive = frontier > .5 && mass < 1.0;
      let noise = .82 + .36 * hash(vec2f(f32(x), f32(y)));
      if (receptive) {
        let rate =
          min(
            v,
            (.035 + v * .43) * anisotropy * noise * cold * max(.03, 1.0 - temperature),
          );
        mass += rate;
        v -= rate;
        temperature += rate * .12;
      }
      if (mass >= 1.0) {
        mass = 1.0;
        v = 0.0;
      }
      let brush = exp(-dot(uv - hand, uv - hand) * 1900.0) * press;
      if (tool < .5 && brush > .52) {
        mass = 1.0;
        v = 0.0;
        temperature = -.3;
      }
      if (tool > .5) {
        let melt = brush * .42;
        mass = max(0.0, mass - melt);
        v += melt * .3;
        temperature += brush * .6;
      }
      if (x < 2 || y < 2 || x > i32(size) - 3 || y > i32(size) - 3) {
        v = .72;
        mass = 0.0;
      }
      next[i] =
        vec4f(
          clamp(mass, 0.0, 1.0),
          clamp(v, 0.0, 1.0),
          clamp(temperature, -1.0, 2.0),
          s.w + select(0.0, .01, mass > .02),
        );
    }
  `,
  }),
);
await Promise.all(steps.map((step) => step.prepare()));
// Download tactile.ts for the complete simulation and crystalline renderer.

silk-cloth:
import { Buffer, GpuContext, rawKernel } from 'wgpu-kit';

/** A small, genuine XPBD cloth solver. No particle pack, textures, or image assets. */
export const SILK_METADATA = {
  id: 'silk-cloth',
  title: 'Silk atelier',
  description:
    'Grab a sheet of silk. GPU distance constraints turn your gesture into folds, weight, and satin highlights.',
  tags: ['rawKernel', 'XPBD', 'compute geometry'],
  hint: 'Drag the silk to gather it. Release to let the folds settle. Arrow keys move the grip; Space releases it.',
  parameter: 'Breeze',
  min: 0,
  max: 2,
  step: 0.01,
  value: 0.65,
};

const PARAMS = `
    struct Params {
      grid: vec4f,
      hand: vec4f,
      motion: vec4f,
      screen: vec4f,
    }
  `;
export const SILK_INTEGRATE = `
${PARAMS}
    @group(0) @binding(0) var<storage, read_write> position: array<vec4f>;
    @group(0) @binding(1) var<storage, read_write> previous: array<vec4f>;
    @group(0) @binding(2) var<uniform> p: Params;

    @compute @workgroup_size(64)
    fn main(@builtin(global_invocation_id) gid: vec3u) {
      let i = gid.x;
      if (i >= u32(p.grid.x * p.grid.y)) {
        return;
      }
      let old = position[i];
      if (i == u32(p.hand.w)) {
        position[i] = vec4f(p.hand.xyz, old.w);
        previous[i] = position[i];
        return;
      }
      if (old.w == 0.0) {
        return;
      }
      let uv =
        vec2f(
          f32(i % u32(p.grid.x)) / (p.grid.x - 1.0),
          f32(i / u32(p.grid.x)) / (p.grid.y - 1.0),
        );
      let gust =
        sin(p.motion.y * 1.1 + uv.x * 5.0 + uv.y * 3.0) * .7 + sin(
          p.motion.y * .63 - uv.y * 7.0,
        ) * .3;
      let force = vec3f(.15 * gust * p.motion.z, -1.2, (.35 + gust) * p.motion.z);
      let velocity = (old.xyz - previous[i].xyz) * .983;
      previous[i] = old;
      var next = old.xyz + velocity + force * p.motion.x * p.motion.x;
      // A soft safety volume prevents extreme pointer movement from losing the cloth.
      next = clamp(next, vec3f(-2, -1.8, -1), vec3f(2, 1.5, 1));
      position[i] = vec4f(next, old.w);
    }
  `;

export const SILK_CONSTRAINT = `
${PARAMS}
    @group(0) @binding(0) var<storage, read_write> position: array<vec4f>;
    @group(0) @binding(1) var<storage, read> edges: array<vec4f>;
    @group(0) @binding(2) var<storage, read_write> multipliers: array<f32>;
    @group(0) @binding(3) var<uniform> p: Params;

    @compute @workgroup_size(64)
    fn main(@builtin(global_invocation_id) gid: vec3u) {
      let i = gid.x;
      if (i >= arrayLength(&edges)) {
        return;
      }
      let e = edges[i];
      let a = u32(e.x);
      let b = u32(e.y);
      let pa = position[a];
      let pb = position[b];
      let wa = select(pa.w, 0.0, a == u32(p.hand.w));
      let wb = select(pb.w, 0.0, b == u32(p.hand.w));
      if (wa + wb == 0.0) {
        return;
      }
      let d = pa.xyz - pb.xyz;
      let len = length(d);
      if (len < .000001) {
        return;
      }
      let alpha = e.w / (p.motion.x * p.motion.x);
      let dl = (-(len - e.z) - alpha * multipliers[i]) / (wa + wb + alpha);
      multipliers[i] += dl;
      let correction = dl * d / len;
      position[a] = vec4f(pa.xyz + wa * correction, pa.w);
      position[b] = vec4f(pb.xyz - wb * correction, pb.w);
    }
  `;

export const SILK_RENDER = `
${PARAMS}
    @group(0) @binding(0) var<storage, read> position: array<vec4f>;
    @group(0) @binding(1) var<uniform> p: Params;

    struct V {
      @builtin(position) clip: vec4f,
      @location(0) world: vec3f,
      @location(1) normal: vec3f,
      @location(2) tangent: vec3f,
      @location(3) uv: vec2f,
    }

    fn at(x: i32, y: i32) -> vec3f {
      return
        position[u32(clamp(y, 0, i32(p.grid.y) - 1)) * u32(p.grid.x) + u32(
          clamp(x, 0, i32(p.grid.x) - 1),
        )].xyz;
    }

    @vertex
    fn vs(@builtin(vertex_index) id: u32) -> V {
      let nx = u32(p.grid.x);
      let cell = id / 6u;
      let c =
        array<vec2u, 6>(
          vec2u(0, 0),
          vec2u(1, 0),
          vec2u(0, 1),
          vec2u(0, 1),
          vec2u(1, 0),
          vec2u(1, 1),
        )[id % 6u];
      let xy = vec2u(cell % (nx - 1u), cell / (nx - 1u)) + c;
      let w = at(i32(xy.x), i32(xy.y));
      // A wider, weighted geometric normal removes grid-aligned highlight chatter.
      let x = i32(xy.x);
      let y = i32(xy.y);
      let dx =
        (at(x + 2, y) - at(x - 2, y)) * 2.0
          + at(x + 2, y - 1)
          - at(x - 2, y - 1)
          + at(x + 2, y + 1)
          - at(x - 2, y + 1);
      let dy =
        (at(x, y + 2) - at(x, y - 2)) * 2.0
          + at(x - 1, y + 2)
          - at(x - 1, y - 2)
          + at(x + 1, y + 2)
          - at(x + 1, y - 2);
      var o: V;
      o.clip =
        vec4f(
          (w.x + w.z * .18) * p.screen.z / p.screen.x,
          (w.y + w.z * .06) * p.screen.z,
          .5 - w.z * .1,
          1,
        );
      o.world = w;
      o.normal = normalize(cross(dy, dx));
      o.tangent = normalize(dx);
      o.uv = vec2f(xy) / vec2f(p.grid.xy - 1.0);
      return o;
    }

    @fragment
    fn fs(v: V, @builtin(front_facing) front: bool) -> @location(0) vec4f {
      let eye = normalize(vec3f(.18, .06, 3) - v.world);
      let normal = normalize(v.normal);
      let n = normal * select(-1.0, 1.0, dot(normal, eye) >= 0.0);
      let t = normalize(v.tangent);
      let b = normalize(cross(n, t));
      let light = normalize(vec3f(-1.4, .30, 2.0));
      let half = normalize(light + eye);
      let nl = max(0.0, dot(n, light));
      let nh = max(.001, dot(n, half));
      // A normalized anisotropic lobe follows the actual deformed warp/weft frame.
      let ax = .42;
      let ay = .085;
      let tx = dot(t, half) / ax;
      let by = dot(b, half) / ay;
      let spec =
        exp(-(tx * tx + by * by) / (nh * nh)) / (4.0
          * 3.14159
          * ax
          * ay
          * max(.16, nh * nh * nh * nh));
      let edge = pow(1.0 - abs(dot(n, eye)), 3.0);
      let warp = .5 + .5 * sin(v.uv.x * 1600.0);
      let weft = .5 + .5 * sin(v.uv.y * 1200.0);
      let aa =
        clamp(1.0 - max(fwidth(v.uv.x) * 255.0, fwidth(v.uv.y) * 190.0), 0.0, 1.0);
      let weave = (warp * weft - .25) * .025 * aa;
      let base = mix(vec3f(.012, .027, .095), vec3f(.009, .047, .085), p.screen.w);
      var color =
        base * (.19 + .75 * nl + weave)
          + vec3f(.34, .79, .87) * spec * .11
          + vec3f(.035, .18, .28) * edge * .12;
      let rim = min(min(v.uv.x, 1.0 - v.uv.x), min(v.uv.y, 1.0 - v.uv.y));
      let hem = 1.0 - smoothstep(.008, .015, rim);
      color = mix(color, color * .7 + vec3f(.055, .068, .10), hem * .32);
      color = color / (color + vec3f(.7));
      return vec4f(pow(color, vec3f(.4545)), 1);
    }
  `;

export type SilkController = {
  destroy(): void;
  setPaused(v: boolean): void;
  reset(): void;
  setParameter(key: string, value: number): void;
};

/** Greedy coloring produces disjoint edges within each dispatch: no float atomics or write races. */
export function makeSilkModel(nx = 65, ny = 49) {
  const initial = new Float32Array(nx * ny * 4);
  for (let y = 0; y < ny; y++)
    for (let x = 0; x < nx; x++) {
      const u = x / (nx - 1),
        v = y / (ny - 1),
        i = (y * nx + x) * 4;
      initial.set(
        [
          (u - 0.5) * 2.12,
          0.82 - v * 1.5 - 0.16 * Math.sin(u * Math.PI) * (1 - v * 0.35),
          0.15 * Math.sin(u * Math.PI * 3) * (0.15 + 0.85 * v) +
            0.06 * Math.sin(u * Math.PI) * Math.sin(v * Math.PI),
          y === 0 && (x === 0 || x === nx - 1) ? 0 : 1,
        ],
        i,
      );
    }
  const edges: number[][] = [];
  const add = (a: number, b: number, compliance: number) => {
    const d = Math.hypot(
      initial[a * 4] - initial[b * 4],
      initial[a * 4 + 1] - initial[b * 4 + 1],
      initial[a * 4 + 2] - initial[b * 4 + 2],
    );
    edges.push([a, b, d, compliance]);
  };
  for (let y = 0; y < ny; y++)
    for (let x = 0; x < nx; x++) {
      const i = y * nx + x;
      if (x + 1 < nx) add(i, i + 1, 0);
      if (y + 1 < ny) add(i, i + nx, 0);
      if (x + 1 < nx && y + 1 < ny) {
        add(i, i + nx + 1, 0.000001);
        add(i + 1, i + nx, 0.000001);
      }
      if (x + 2 < nx) add(i, i + 2, 0.00004);
      if (y + 2 < ny) add(i, i + nx * 2, 0.00004);
    }
  const used = Array.from({ length: nx * ny }, () => new Set<number>());
  const colors: number[][] = [];
  for (const e of edges) {
    let c = 0;
    while (used[e[0]].has(c) || used[e[1]].has(c)) c++;
    used[e[0]].add(c);
    used[e[1]].add(c);
    (colors[c] ??= []).push(...e);
  }
  return { nx, ny, initial, colors: colors.map((v) => new Float32Array(v)) };
}

export async function mountSilk(
  canvas: HTMLCanvasElement,
  onStatus: (s: string) => void,
  options: { reducedMotion?: boolean; theme?: string; onFrame?: () => void } = {},
): Promise<SilkController> {
  const { device } = await GpuContext.get();
  const surface = canvas.getContext('webgpu');
  if (!surface) throw Error('A WebGPU canvas is unavailable.');
  const format = navigator.gpu.getPreferredCanvasFormat();
  surface.configure({ device, format, alphaMode: 'opaque' });
  const model = makeSilkModel();
  const count = model.nx * model.ny;
  const position = await Buffer.create('vec4f', count),
    previous = await Buffer.create('vec4f', count);
  const param = device.createBuffer({
    size: 64,
    usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
  });
  const groups = await Promise.all(
    model.colors.map(async (data) => {
      const edges = await Buffer.create('vec4f', data.length / 4);
      edges.write(data);
      return { edges, lambda: await Buffer.create('f32', data.length / 4) };
    }),
  );
  const integrate = rawKernel(SILK_INTEGRATE, 'main', 'silk-verlet-prediction'),
    constrain = rawKernel(SILK_CONSTRAINT, 'main', 'silk-xpbd-colored-constraints');
  await Promise.all([integrate.prepare(), constrain.prepare()]);
  const shader = device.createShaderModule({
    code: SILK_RENDER,
    label: 'silk-anisotropic-satin',
  });
  const pipeline = await device.createRenderPipelineAsync({
    layout: 'auto',
    vertex: { module: shader, entryPoint: 'vs' },
    fragment: { module: shader, entryPoint: 'fs', targets: [{ format }] },
    primitive: { cullMode: 'none' },
    depthStencil: {
      format: 'depth24plus',
      depthCompare: 'less',
      depthWriteEnabled: true,
    },
  });
  const group = device.createBindGroup({
    layout: pipeline.getBindGroupLayout(0),
    entries: [
      { binding: 0, resource: { buffer: position.gpuBuffer } },
      { binding: 1, resource: { buffer: param } },
    ],
  });
  let ready = false;
  let canvasRect = canvas.getBoundingClientRect();
  function requestDraw() {
    if (ready && !dead && visible && !document.hidden && !frame)
      frame = requestAnimationFrame(draw);
  }
  const visibility = () => {
    last = 0;
    if (document.hidden) {
      cancelAnimationFrame(frame);
      frame = 0;
    } else {
      dirty = true;
      requestDraw();
    }
  };
  document.addEventListener('visibilitychange', visibility);
  let accumulator = 0;
  let dead = false,
    paused = !!options.reducedMotion,
    visible = true,
    dirty = true,
    time = 0,
    frame = 0,
    last = 0,
    wind = 0.65,
    light = options.theme === 'light' ? 1 : 0;
  let depth: GPUTexture | null = null,
    width = 0,
    height = 0,
    grab = -1,
    down = false,
    token = 0,
    hand = [0, 0, 0.4];
  const entries = [
    { binding: 0, resource: { buffer: position.gpuBuffer } },
    { binding: 1, resource: { buffer: previous.gpuBuffer } },
    { binding: 2, resource: { buffer: param } },
  ];
  const edgeEntries = groups.map((g) => [
    { binding: 0, resource: { buffer: position.gpuBuffer } },
    { binding: 1, resource: { buffer: g.edges.gpuBuffer } },
    { binding: 2, resource: { buffer: g.lambda.gpuBuffer } },
    { binding: 3, resource: { buffer: param } },
  ]);
  const reset = () => {
    position.write(model.initial);
    previous.write(model.initial);
    grab = -1;
    down = false;
    token++;
    time = 0;
    last = 0;
    accumulator = 0;
    dirty = true;
    requestDraw();
  };
  reset();
  const point = (e: PointerEvent) => {
    const r = canvas.getBoundingClientRect();
    return {
      x: ((e.clientX - r.left) / r.width) * 2 - 1,
      y: 1 - ((e.clientY - r.top) / r.height) * 2,
      aspect: r.width / r.height,
    };
  };
  const updateHand = (e: PointerEvent) => {
    const q = point(e);
    hand[0] = Math.max(-1.5, Math.min(1.5, (q.x * q.aspect) / 0.9 - hand[2] * 0.18));
    hand[1] = Math.max(-1.15, Math.min(1.15, q.y / 0.9 - hand[2] * 0.06));
    dirty = true;
    requestDraw();
  };
  const press = async (e: PointerEvent) => {
    if (e.button !== 0) return;
    down = true;
    const ticket = ++token;
    canvas.setPointerCapture(e.pointerId);
    canvas.focus({ preventScroll: true });
    const q = point(e);
    try {
      const data = await position.read();
      if (dead || !down || ticket !== token) return;
      let best = 0.13 * 0.13,
        found = -1;
      for (let i = 0; i < count; i++) {
        if (data[i * 4 + 3] === 0) continue;
        const x = ((data[i * 4] + data[i * 4 + 2] * 0.18) * 0.9) / q.aspect,
          y = (data[i * 4 + 1] + data[i * 4 + 2] * 0.06) * 0.9;
        const d = (x - q.x) ** 2 + (y - q.y) ** 2;
        if (d < best) {
          best = d;
          found = i;
        }
      }
      if (found >= 0) {
        grab = found;
        hand = [
          data[found * 4],
          data[found * 4 + 1],
          Math.min(0.65, data[found * 4 + 2] + 0.18),
        ];
        updateHand(e);
      }
    } catch (err) {
      if (!dead) onStatus('GPU error: ' + String(err));
    }
  };
  const move = (e: PointerEvent) => {
    if (down && grab >= 0) updateHand(e);
  };
  const release = () => {
    down = false;
    grab = -1;
    token++;
    dirty = true;
    requestDraw();
  };
  const key = (e: KeyboardEvent) => {
    if (e.key === ' ') {
      e.preventDefault();
      release();
      return;
    }
    if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
    e.preventDefault();
    if (grab < 0) {
      grab = Math.floor(model.ny * 0.55) * model.nx + Math.floor(model.nx / 2);
      hand = [0, 0, 0.4];
    }
    if (e.key === 'ArrowLeft') hand[0] -= 0.045;
    if (e.key === 'ArrowRight') hand[0] += 0.045;
    if (e.key === 'ArrowUp') hand[1] += 0.045;
    if (e.key === 'ArrowDown') hand[1] -= 0.045;
    dirty = true;
    requestDraw();
  };
  canvas.addEventListener('pointerdown', press);
  canvas.addEventListener('pointermove', move);
  canvas.addEventListener('pointerup', release);
  canvas.addEventListener('pointercancel', release);
  canvas.addEventListener('lostpointercapture', release);
  canvas.addEventListener('keydown', key);
  canvas.style.touchAction = 'none';
  const observer = new IntersectionObserver((es) => {
    visible = es[0].isIntersecting;
    last = 0;
    dirty = true;
    requestDraw();
  });
  observer.observe(canvas);
  const resizeObserver = new ResizeObserver(() => {
    canvasRect = canvas.getBoundingClientRect();
    dirty = true;
    requestDraw();
    last = 0;
  });
  resizeObserver.observe(canvas);
  const error = (e: GPUUncapturedErrorEvent) => {
    if (!dead) {
      paused = true;
      onStatus('GPU error: ' + e.error.message);
    }
  };
  device.addEventListener('uncapturederror', error);
  const draw = (now: number) => {
    frame = 0;
    if (dead) return;
    if (!visible || document.hidden || (paused && !dirty)) return;
    const dt = last ? Math.min(0.033, (now - last) / 1000) : 1 / 60;
    last = now;
    if (!paused) time += dt;
    dirty = false;
    const r = canvasRect,
      d = Math.min(
        devicePixelRatio || 1,
        1.5,
        Math.sqrt(750000 / Math.max(1, r.width * r.height)),
      ),
      w = Math.max(1, Math.round(r.width * d)),
      h = Math.max(1, Math.round(r.height * d));
    if (w !== width || h !== height) {
      width = w;
      height = h;
      canvas.width = w;
      canvas.height = h;
      depth?.destroy();
      depth = device.createTexture({
        size: [w, h],
        format: 'depth24plus',
        usage: GPUTextureUsage.RENDER_ATTACHMENT,
      });
    }
    const subdt = 1 / 120;
    if (!paused) accumulator = Math.min(accumulator + dt, 0.034);
    const substeps = Math.min(4, Math.floor(accumulator / subdt));
    if (!paused) accumulator -= substeps * subdt;
    device.queue.writeBuffer(
      param,
      0,
      new Float32Array([
        model.nx,
        model.ny,
        0,
        0,
        ...hand,
        grab < 0 ? count : grab,
        subdt,
        time,
        wind,
        0,
        width / height,
        height,
        0.9,
        light,
      ]),
    );
    try {
      const encoder = device.createCommandEncoder();
      if (!paused) {
        for (let s = 0; s < substeps; s++) {
          for (const g of groups) encoder.clearBuffer(g.lambda.gpuBuffer);
          integrate.encode(encoder, entries, Math.ceil(count / 64));
          for (let k = 0; k < 4; k++)
            groups.forEach((g, i) =>
              constrain.encode(encoder, edgeEntries[i], Math.ceil(g.edges.length / 64)),
            );
        }
      }
      const bg = {
        r: 0.018 + (0.72 - 0.018) * light,
        g: 0.028 + (0.76 - 0.028) * light,
        b: 0.038 + (0.76 - 0.038) * light,
        a: 1,
      };
      const pass = encoder.beginRenderPass({
        colorAttachments: [
          {
            view: surface.getCurrentTexture().createView(),
            loadOp: 'clear',
            storeOp: 'store',
            clearValue: bg,
          },
        ],
        depthStencilAttachment: {
          view: depth!.createView(),
          depthClearValue: 1,
          depthLoadOp: 'clear',
          depthStoreOp: 'store',
        },
      });
      pass.setPipeline(pipeline);
      pass.setBindGroup(0, group);
      pass.draw((model.nx - 1) * (model.ny - 1) * 6);
      pass.end();
      device.queue.submit([encoder.finish()]);
      options.onFrame?.();
    } catch (e) {
      paused = true;
      onStatus('GPU error: ' + String(e));
    }
    if (!paused) requestDraw();
  };
  ready = true;
  requestDraw();
  onStatus('Live WebGPU · wgpu-kit 2.0.1');
  return {
    destroy() {
      if (dead) return;
      dead = true;
      document.removeEventListener('visibilitychange', visibility);
      token++;
      cancelAnimationFrame(frame);
      observer.disconnect();
      resizeObserver.disconnect();
      canvas.removeEventListener('pointerdown', press);
      canvas.removeEventListener('pointermove', move);
      canvas.removeEventListener('pointerup', release);
      canvas.removeEventListener('pointercancel', release);
      canvas.removeEventListener('lostpointercapture', release);
      canvas.removeEventListener('keydown', key);
      device.removeEventListener('uncapturederror', error);
      integrate.destroy();
      constrain.destroy();
      position.destroy();
      previous.destroy();
      groups.forEach((g) => {
        g.edges.destroy();
        g.lambda.destroy();
      });
      param.destroy();
      depth?.destroy();
      surface.unconfigure();
    },
    setPaused(v) {
      paused = v;
      if (v) {
        down = false;
        grab = -1;
        token++;
      }
      last = 0;
      dirty = true;
      requestDraw();
    },
    reset,
    setParameter(key, value) {
      if (key === 'amount') wind = Math.max(0, Math.min(2, value));
      if (key === 'theme') light = value;
      dirty = true;
      requestDraw();
    },
  };
}

gravitational-lens:
import { GpuContext, Buffer, elementKernel } from 'wgpu-kit';

export const LENS_UNIFORMS = {
  size: 'u32',
  time: 'f32',
  pointer: 'vec2f',
  amount: 'f32',
  aspect: 'f32',
  light: 'f32',
  lensing: 'f32',
  grid: 'f32',
} as const;

export const LENS_SHADER = `
    // A source-plane atlas, sampled by the point-mass thin-lens equation.
    // Units are dimensionless angular coordinates. No artificial accretion disk.
    fn lensHash(p: vec2f) -> f32 {
      return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453);
    }

    fn lensNoise(p: vec2f) -> f32 {
      let cell = floor(p);
      let f = fract(p);
      let u = f * f * (3.0 - 2.0 * f);
      return
        mix(
          mix(lensHash(cell), lensHash(cell + vec2f(1, 0)), u.x),
          mix(lensHash(cell + vec2f(0, 1)), lensHash(cell + vec2f(1, 1)), u.x),
          u.y,
        );
    }

    fn rotateLens(p: vec2f, a: f32) -> vec2f {
      return vec2f(cos(a) * p.x - sin(a) * p.y, sin(a) * p.x + cos(a) * p.y);
    }

    fn atlasStars(p: vec2f, density: f32, seed: f32) -> vec3f {
      let cell = floor(p * density);
      let f = fract(p * density) - 0.5;
      let h = lensHash(cell + seed);
      let center =
        (vec2f(lensHash(cell + 19.7 + seed), lensHash(cell + 81.3)) - 0.5) * 0.62;
      let delta = f - center;
      let r2 = dot(delta, delta);
      let radius = mix(0.035, 0.085, h * h);
      let star = exp(-r2 / (radius * radius)) + 0.055 * exp(-r2 / 0.05);
      let tint =
        mix(vec3f(0.40, 0.65, 1.0), vec3f(1.0, 0.76, 0.43), lensHash(cell + 6.8));
      return tint * star * step(0.66, h) * (0.48 + h);
    }

    fn spiralGalaxy(
      p: vec2f,
      center: vec2f,
      radius: f32,
      angle: f32,
      tint: vec3f,
    ) -> vec3f {
      let q = rotateLens((p - center) / radius, angle) * vec2f(1.0, 1.7);
      let r = length(q);
      let a = atan2(q.y, q.x);
      let spiral = 0.5 + 0.5 * cos(2.0 * a - 5.8 * log(r + 0.13));
      let arms = pow(spiral, 9.0) * exp(-r * 1.65) * smoothstep(0.12, 0.48, r);
      let texture = 0.52 + 0.48 * lensNoise(q * 21.0);
      let disk = exp(-r * r * 2.0) * 0.11;
      let core = exp(-r * r * 55.0);
      let knots = pow(lensNoise(q * 16.0 + 8.3), 8.0) * arms;
      return
        tint * (disk + arms * texture * 2.9 + knots * 3.0) + vec3f(1.0, 0.88, 0.67)
          * core
          * 1.25;
    }

    fn atlasLine(p: vec2f, a: vec2f, b: vec2f) -> f32 {
      let ab = b - a;
      let distanceToLine =
        length(p - a - ab * clamp(dot(p - a, ab) / dot(ab, ab), 0.0, 1.0));
      return exp(-distanceToLine * distanceToLine / 0.000010);
    }

    fn sourceAtlas(beta: vec2f, showGrid: f32) -> vec3f {
      var result = vec3f(0.008, 0.015, 0.030);
      let band = beta.y + 0.28 * sin(beta.x * 1.5) + 0.16;
      let dust = exp(-band * band * 7.0) * (0.28 + 0.72 * lensNoise(beta * 5.0));
      result += vec3f(0.023, 0.032, 0.065) * dust;
      result += atlasStars(beta, 23.0, 3.2);
      result += atlasStars(beta + 13.5, 47.0, 7.1) * 0.42;

      // The same three recognizable galaxies exist in the lensed and unlensed views.
      result +=
        spiralGalaxy(beta, vec2f(0.075, -0.025), 0.32, -0.35, vec3f(0.31, 0.69, 1.0));
      result +=
        spiralGalaxy(beta, vec2f(-0.94, 0.40), 0.25, 0.65, vec3f(1.0, 0.52, 0.27));
      result +=
        spiralGalaxy(beta, vec2f(0.96, -0.36), 0.27, -0.72, vec3f(0.76, 0.43, 1.0));

      // A sparse atlas constellation provides a second, geometric distortion cue.
      let a = vec2f(-0.59, -0.59);
      let b = vec2f(-0.24, -0.48);
      let c = vec2f(0.24, -0.67);
      let d = vec2f(0.66, -0.51);
      result +=
        vec3f(0.12, 0.23, 0.32) * (atlasLine(beta, a, b)
          + atlasLine(beta, b, c)
          + atlasLine(beta, c, d));
      for (var i = 0u; i < 4u; i++) {
        let point = array<vec2f, 4>(a, b, c, d)[i];
        result +=
          vec3f(0.61, 0.83, 1.0) * exp(-dot(beta - point, beta - point) / 0.00013);
      }
      if (showGrid > 0.5) {
        let q = abs(fract(beta / 0.20 + 0.5) - 0.5) * 0.20;
        let grid = 1.0 - smoothstep(0.001, 0.004, min(q.x, q.y));
        result += vec3f(0.09, 0.23, 0.28) * grid;
      }
      return result;
    }

    fn userFn(
      idx: u32,
      size: u32,
      time: f32,
      pointer: vec2f,
      amount: f32,
      aspect: f32,
      light: f32,
      lensing: f32,
      grid: f32,
    ) {
      let uv = (vec2f(f32(idx % size), f32(idx / size)) + 0.5) / f32(size);
      let theta = (uv - 0.5) * vec2f(2.0 * aspect, 2.0);
      let lens = pointer;
      let offset = theta - lens;
      let radiusSquared = dot(offset, offset);
      // thetaE squared is proportional to mass at fixed observer/lens/source distances.
      let thetaESquared = 0.22 * max(amount, 0.0);
      var beta = theta;
      if (lensing > 0.5) {
        // Inverse ray mapping: observed image angle -> unlensed source angle.
        // The tiny denominator floor only handles the point singularity numerically.
        beta = theta - thetaESquared * offset / max(radiusSquared, 0.000001);
      }
      var rgb = sourceAtlas(beta, grid);
      // A small, non-emissive crosshair marks the lens; this is an interface overlay.
      let cross =
        (1.0 - smoothstep(0.0015, 0.004, min(abs(offset.x), abs(offset.y))))
          * smoothstep(0.010, 0.014, length(offset))
          * (1.0 - smoothstep(0.032, 0.039, length(offset)));
      rgb = mix(rgb, vec3f(0.72, 0.84, 0.92), cross * 0.70);
      // Identical exposure in both views preserves the source's surface brightness.
      rgb = vec3f(1.0) - exp(-rgb * 1.28);
      color[idx] = vec4f(rgb, 1.0);
    }
  `;

export const LENS_PRESENT = `
    @group(0) @binding(0) var<storage, read> pixels: array<vec4f>;
    @group(0) @binding(1) var<uniform> screen: vec4u;

    struct VertexOutput {
      @builtin(position) position: vec4f,
      @location(0) uv: vec2f,
    }

    @vertex
    fn vs(@builtin(vertex_index) index: u32) -> VertexOutput {
      let positions = array<vec2f, 3>(vec2f(-1, -1), vec2f(3, -1), vec2f(-1, 3));
      var result: VertexOutput;
      result.position = vec4f(positions[index], 0, 1);
      result.uv = positions[index] * vec2f(0.5, -0.5) + 0.5;
      return result;
    }

    @fragment
    fn fs(input: VertexOutput) -> @location(0) vec4f {
      // Bilinear presentation of the compute result, including non-square canvases.
      let xy =
        clamp(input.uv * f32(screen.x) - 0.5, vec2f(0), vec2f(f32(screen.x - 1u)));
      let lo = vec2u(floor(xy));
      let hi = min(lo + vec2u(1), vec2u(screen.x - 1u));
      let fraction = fract(xy);
      return
        mix(
          mix(
            pixels[lo.y * screen.x + lo.x],
            pixels[lo.y * screen.x + hi.x],
            fraction.x,
          ),
          mix(
            pixels[hi.y * screen.x + lo.x],
            pixels[hi.y * screen.x + hi.x],
            fraction.x,
          ),
          fraction.y,
        );
    }
  `;

export type LensController = {
  destroy(): void;
  setPaused(value: boolean): void;
  reset(): void;
  setParameter(key: string, value: number): void;
};

/** Mount the point-mass thin-lens example into the existing showcase shell. */
export async function mountGravitationalLens(
  canvas: HTMLCanvasElement,
  onStatus: (status: string) => void,
  options: { reducedMotion?: boolean; theme?: string } = {},
): Promise<LensController> {
  const context = await GpuContext.get();
  const device = context.device;
  const surface = canvas.getContext('webgpu');
  if (!surface) throw new Error('A WebGPU canvas is unavailable.');
  const format = navigator.gpu.getPreferredCanvasFormat();
  surface.configure({ device, format, alphaMode: 'opaque' });

  const size = 640;
  const color = await Buffer.create('vec4f', size * size);
  const screen = device.createBuffer({
    size: 16,
    usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
  });
  device.queue.writeBuffer(screen, 0, new Uint32Array([size, 0, 0, 0]));
  const kernel = elementKernel({
    name: 'gravitational-thin-lens',
    state: { color: 'vec4f' },
    uniforms: LENS_UNIFORMS,
    code: LENS_SHADER,
  });
  let pipeline: GPURenderPipeline;
  let bindings: GPUBindGroup;
  try {
    await kernel.prepare();
    const module = device.createShaderModule({ code: LENS_PRESENT });
    pipeline = await device.createRenderPipelineAsync({
      layout: 'auto',
      vertex: { module, entryPoint: 'vs' },
      fragment: { module, entryPoint: 'fs', targets: [{ format }] },
      primitive: { topology: 'triangle-list' },
    });
    bindings = device.createBindGroup({
      layout: pipeline.getBindGroupLayout(0),
      entries: [
        { binding: 0, resource: { buffer: color.gpuBuffer } },
        { binding: 1, resource: { buffer: screen } },
      ],
    });
  } catch (error) {
    kernel.destroy();
    color.destroy();
    screen.destroy();
    surface.unconfigure();
    throw error;
  }

  let dead = false;
  let failed = false;
  let visible = true;
  let frame = 0;
  let activePointer: number | null = null;
  let amount = 1;
  let lensing = 1;
  let grid = 0;
  let pointer = { x: 0, y: 0 };
  let light = options.theme === 'light' ? 1 : 0;
  const previousTouchAction = canvas.style.touchAction;
  const abort = new AbortController();

  const request = () => {
    if (!dead && !failed && !frame) frame = requestAnimationFrame(draw);
  };
  const draw = () => {
    frame = 0;
    if (dead || failed || !visible || document.hidden) return;
    const bounds = canvas.getBoundingClientRect();
    if (bounds.width <= 0 || bounds.height <= 0) return;
    const scale = Math.min(
      devicePixelRatio || 1,
      1.5,
      Math.sqrt(1500000 / Math.max(1, bounds.width * bounds.height)),
    );
    const width = Math.max(1, Math.round(bounds.width * scale));
    const height = Math.max(1, Math.round(bounds.height * scale));
    if (canvas.width !== width) canvas.width = width;
    if (canvas.height !== height) canvas.height = height;
    try {
      // Compute and presentation share one encoder, in the public composition API.
      const encoder = device.createCommandEncoder();
      kernel.encode(
        encoder,
        { color },
        {
          size,
          time: 0,
          pointer,
          amount,
          aspect: width / height,
          light,
          lensing,
          grid,
        },
      );
      const pass = encoder.beginRenderPass({
        colorAttachments: [
          {
            view: surface.getCurrentTexture().createView(),
            loadOp: 'clear',
            storeOp: 'store',
            clearValue: { r: 0, g: 0, b: 0, a: 1 },
          },
        ],
      });
      pass.setPipeline(pipeline);
      pass.setBindGroup(0, bindings);
      pass.draw(3);
      pass.end();
      device.queue.submit([encoder.finish()]);
      kernel.endSubmit();
    } catch (error) {
      failed = true;
      onStatus('GPU error: ' + String(error));
    }
  };

  const move = (event: PointerEvent) => {
    if (activePointer !== event.pointerId) return;
    const bounds = canvas.getBoundingClientRect();
    if (bounds.width <= 0 || bounds.height <= 0) return;
    pointer = {
      x:
        ((((event.clientX - bounds.left) / bounds.width) * 2 - 1) * bounds.width) /
        bounds.height,
      y: ((event.clientY - bounds.top) / bounds.height) * 2 - 1,
    };
    request();
  };
  const down = (event: PointerEvent) => {
    if (!event.isPrimary || event.button !== 0) return;
    activePointer = event.pointerId;
    canvas.setPointerCapture(event.pointerId);
    canvas.focus({ preventScroll: true });
    move(event);
  };
  const up = (event: PointerEvent) => {
    if (activePointer !== event.pointerId) return;
    if (canvas.hasPointerCapture(event.pointerId))
      canvas.releasePointerCapture(event.pointerId);
    activePointer = null;
  };
  const key = (event: KeyboardEvent) => {
    const step = event.shiftKey ? 0.1 : 0.025;
    if (event.key === 'ArrowLeft') pointer.x -= step;
    else if (event.key === 'ArrowRight') pointer.x += step;
    else if (event.key === 'ArrowUp') pointer.y -= step;
    else if (event.key === 'ArrowDown') pointer.y += step;
    else return;
    event.preventDefault();
    const aspect = canvas.width / Math.max(1, canvas.height);
    pointer.x = Math.max(-aspect, Math.min(aspect, pointer.x));
    pointer.y = Math.max(-1, Math.min(1, pointer.y));
    request();
  };
  const error = (event: GPUUncapturedErrorEvent) => {
    failed = true;
    if (!dead) onStatus('GPU error: ' + event.error.message);
  };
  canvas.style.touchAction = 'none';
  canvas.addEventListener('pointerdown', down, { signal: abort.signal });
  canvas.addEventListener('pointermove', move, { signal: abort.signal });
  canvas.addEventListener('pointerup', up, { signal: abort.signal });
  canvas.addEventListener('pointercancel', up, { signal: abort.signal });
  canvas.addEventListener(
    'lostpointercapture',
    () => {
      activePointer = null;
    },
    { signal: abort.signal },
  );
  canvas.addEventListener('keydown', key, { signal: abort.signal });
  document.addEventListener('visibilitychange', request, {
    signal: abort.signal,
  });
  device.addEventListener('uncapturederror', error);
  const observer = new IntersectionObserver((entries) => {
    visible = entries[0].isIntersecting;
    if (visible) request();
  });
  const resizeObserver = new ResizeObserver(request);
  observer.observe(canvas);
  resizeObserver.observe(canvas);
  device.lost.then((info) => {
    if (!dead) {
      failed = true;
      onStatus('GPU device lost: ' + info.message);
    }
  });
  request();
  onStatus('Live WebGPU · wgpu-kit 2.0.1');

  return {
    destroy() {
      if (dead) return;
      dead = true;
      cancelAnimationFrame(frame);
      if (activePointer !== null && canvas.hasPointerCapture(activePointer))
        canvas.releasePointerCapture(activePointer);
      abort.abort();
      observer.disconnect();
      resizeObserver.disconnect();
      device.removeEventListener('uncapturederror', error);
      canvas.style.touchAction = previousTouchAction;
      kernel.destroy();
      color.destroy();
      screen.destroy();
      surface.unconfigure();
    },
    // There is no time animation: the atlas stays fixed for an exact comparison.
    // The showcase may hide Pause for this example. Input always requests a frame.
    setPaused() {
      request();
    },
    reset() {
      pointer = { x: 0, y: 0 };
      amount = 1;
      lensing = 1;
      grid = 0;
      request();
    },
    setParameter(key, value) {
      if (!Number.isFinite(value)) return;
      if (key === 'amount') amount = Math.max(0.25, Math.min(2.5, value));
      if (key === 'lensing') lensing = value > 0.5 ? 1 : 0;
      if (key === 'grid') grid = value > 0.5 ? 1 : 0;
      if (key === 'theme') light = value;
      if (key === 'align') pointer = { x: 0.075, y: -0.025 };
      request();
    },
  };
}

sculpted-ribbon:
import { Buffer, GpuContext, PingPong, elementKernel } from 'wgpu-kit';

/** Original GPU-computed folded ribbon. No image assets or simulation presets. */
export async function mountHero(
  canvas: HTMLCanvasElement,
  onStatus: (status: string) => void = () => {},
  options: { reducedMotion?: boolean } = {},
) {
  const W = 192,
    H = 72,
    N = W * H;
  const ctx = await GpuContext.get();
  const device = ctx.device;
  const context = canvas.getContext('webgpu');
  if (!context) throw new Error('This browser could not create a WebGPU canvas');
  const format = navigator.gpu.getPreferredCanvasFormat();
  context.configure({ device, format, alphaMode: 'premultiplied' });

  const wave = await PingPong.create({ field: 'vec2f' }, N);
  const positions = await Buffer.create('vec4f', N);
  const normals = await Buffer.create('vec4f', N);

  const propagate = elementKernel({
    name: 'Ribbon pressure / wave propagation',
    state: { next: 'vec2f' },
    inputs: { prev: 'vec2f', surface: 'vec4f' },
    uniforms: {
      grid: 'vec2u',
      step: 'f32',
      origin: 'vec3f',
      ray: 'vec3f',
      pressure: 'f32',
    },
    code: `
    fn userFn(
      i: u32,
      grid: vec2u,
      step: f32,
      origin: vec3f,
      ray: vec3f,
      pressure: f32,
    ) {
      let x = i % grid.x;
      let y = i / grid.x;
      let left = y * grid.x + (x + grid.x - 1u) % grid.x;
      let right = y * grid.x + (x + 1u) % grid.x;
      let up = ((y + grid.y - 1u) % grid.y) * grid.x + x;
      let down = ((y + 1u) % grid.y) * grid.x + x;
      let h = prev[i].x;
      let lap = prev[left].x + prev[right].x + prev[up].x + prev[down].x - 4.0 * h;
      let delta = surface[i].xyz - origin;
      let along = dot(delta, ray);
      let toRay = delta - ray * along;
      let brush = exp(-dot(toRay, toRay) * 42.0) * select(0.0, 1.0, along > 0.0);
      let v =
        (prev[i].y + (0.19 * lap - 0.006 * h + pressure * brush) * step) * pow(
          0.978,
          step,
        );
      next[i] = vec2f(clamp(h + v * step, -0.14, 0.14), v);
    }
  `,
  });

  const sculpt = elementKernel({
    name: 'Original folded ribbon / geometry',
    state: { surface: 'vec4f' },
    inputs: { field: 'vec2f' },
    uniforms: { grid: 'vec2u', time: 'f32' },
    code: `
    const TAU: f32 = 6.28318530718;

    fn ribbon(u: f32, v: f32, time: f32) -> vec3f {
      let radial = vec3f(cos(u), 0.0, sin(u));
      let vertical = vec3f(0.0, 1.0, 0.0);
      let radius = 1.15 + 0.10 * cos(3.0 * u + 0.5);
      let center = radial * radius + vertical * (0.20 * sin(2.0 * u));
      let twist = u + 0.28 * sin(2.0 * u + 0.7);
      let wide = radial * cos(twist) + vertical * sin(twist);
      let thin = -radial * sin(twist) + vertical * cos(twist);
      let width = 0.49 + 0.085 * sin(2.0 * u - 0.6);
      let breath = 0.026 * sin(3.0 * u - time * 0.55) * cos(2.0 * v + time * 0.3);
      var p = center + wide * ((width + breath) * cos(v)) + thin * (0.145 * sin(v));
      p.z *= 0.90;
      return p;
    }

    fn userFn(i: u32, grid: vec2u, time: f32) {
      let u = f32(i % grid.x) / f32(grid.x) * TAU;
      let v = f32(i / grid.x) / f32(grid.y) * TAU;
      let p = ribbon(u, v, time);
      let du = ribbon(u + 0.002, v, time) - ribbon(u - 0.002, v, time);
      let dv = ribbon(u, v + 0.002, time) - ribbon(u, v - 0.002, time);
      let normal = normalize(cross(du, dv));
      surface[i] = vec4f(p + normal * field[i].x, 1.0);
    }
  `,
  });

  const deriveNormals = elementKernel({
    name: 'Ribbon surface / finite-difference normals',
    state: { normal: 'vec4f' },
    inputs: { surface: 'vec4f' },
    uniforms: { grid: 'vec2u' },
    code: `
    fn userFn(i: u32, grid: vec2u) {
      let x = i % grid.x;
      let y = i / grid.x;
      let l = y * grid.x + (x + grid.x - 1u) % grid.x;
      let r = y * grid.x + (x + 1u) % grid.x;
      let a = ((y + grid.y - 1u) % grid.y) * grid.x + x;
      let b = ((y + 1u) % grid.y) * grid.x + x;
      normal[i] =
        vec4f(
          normalize(
            cross(surface[r].xyz - surface[l].xyz, surface[b].xyz - surface[a].xyz),
          ),
          0.0,
        );
    }
  `,
  });

  await Promise.all([propagate.prepare(), sculpt.prepare(), deriveNormals.prepare()]);

  const camera = device.createBuffer({
    size: 96,
    usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
  });
  const renderCode = `
    struct Camera {
      matrix: mat4x4f,
      eye: vec4f,
      dimensions: vec4f,
    }

    @group(0) @binding(0) var<uniform> camera: Camera;
    @group(0) @binding(1) var<storage, read> surface: array<vec4f>;
    @group(0) @binding(2) var<storage, read> normal: array<vec4f>;

    struct VertexOut {
      @builtin(position) position: vec4f,
      @location(0) world: vec3f,
      @location(1) norm: vec3f,
      @location(2) uv: vec2f,
    }

    @vertex
    fn vertexMain(@builtin(vertex_index) vertex: u32) -> VertexOut {
      let w = u32(camera.dimensions.x);
      let h = u32(camera.dimensions.y);
      let cell = vertex / 6u;
      let corner = vertex % 6u;
      let dx = select(0u, 1u, corner == 1u || corner == 4u || corner == 5u);
      let dy = select(0u, 1u, corner == 2u || corner == 3u || corner == 5u);
      let x = ((cell % w) + dx) % w;
      let y = ((cell / w) + dy) % h;
      let i = y * w + x;
      var out: VertexOut;
      out.position = camera.matrix * surface[i];
      out.world = surface[i].xyz;
      out.norm = normal[i].xyz;
      out.uv = vec2f(f32(x) / f32(w), f32(y) / f32(h));
      return out;
    }

    fn environment(r: vec3f) -> vec3f {
      var color =
        mix(
          vec3f(0.004, 0.008, 0.016),
          vec3f(0.045, 0.058, 0.079),
          smoothstep(-0.3, 1.0, r.y),
        );
      let strip = pow(max(dot(r, normalize(vec3f(-0.55, 0.80, 0.42))), 0.0), 30.0);
      let blue = pow(max(dot(r, normalize(vec3f(0.85, 0.20, 0.30))), 0.0), 13.0);
      let pink = pow(max(dot(r, normalize(vec3f(-0.60, -0.10, -0.70))), 0.0), 12.0);
      color += vec3f(4.5, 4.6, 4.8) * strip;
      let softbox =
        exp(-pow((r.y - 0.48) * 10.0, 2.0)) * (1.0 - smoothstep(0.62, 0.85, abs(r.x)));
      let rimstrip =
        exp(-pow((r.x + r.z * 0.6 - 0.5) * 18.0, 2.0)) * smoothstep(-0.2, 0.8, r.y);
      color += vec3f(2.7, 3.1, 3.4) * softbox + vec3f(1.1, 0.75, 1.4) * rimstrip;
      color += vec3f(0.10, 0.70, 1.50) * blue;
      color += vec3f(0.78, 0.19, 0.47) * pink;
      color += vec3f(0.20, 0.24, 0.38) * exp(-pow((r.y + 0.08) * 12.0, 2.0));
      return color;
    }

    @fragment
    fn fragmentMain(
      in: VertexOut,
      @builtin(front_facing) front: bool,
    ) -> @location(0) vec4f {
      let n = normalize(in.norm) * select(-1.0, 1.0, front);
      let v = normalize(camera.eye.xyz - in.world);
      let facing = clamp(dot(n, v), 0.0, 1.0);
      let fresnel = pow(1.0 - facing, 4.0);
      let reflected = reflect(-v, n);
      let interference =
        0.5 + 0.5 * cos(vec3f(0.5, 2.6, 4.7) + 4.2 * facing + 0.9 * in.world.y);
      let alloy = mix(vec3f(0.48, 0.55, 0.68), interference * 0.62 + vec3f(0.20), 0.65);
      let ao = mix(0.54, 1.0, smoothstep(0.35, 1.45, length(in.world.xz)));
      let diffuse = 0.018 + 0.08 * max(dot(n, normalize(vec3f(-0.4, 0.8, 0.7))), 0.0);
      var color =
        alloy * diffuse * ao + environment(reflected)
          * mix(alloy, vec3f(1.0), 0.42 + fresnel * 0.58)
          * ao;
      color += vec3f(0.16, 0.33, 0.49) * fresnel * 0.23;
      color = color / (color + vec3f(0.86));
      color = pow(color, vec3f(1.0 / 2.2));
      return vec4f(color, 1.0);
    }
  `;
  const module = device.createShaderModule({
    label: 'Original ribbon / iridescent studio material',
    code: renderCode,
  });
  const diagnostics = await module.getCompilationInfo();
  const shaderErrors = diagnostics.messages.filter((m) => m.type === 'error');
  if (shaderErrors.length)
    throw new Error(
      shaderErrors.map((m) => `Render WGSL ${m.lineNum}: ${m.message}`).join('\n'),
    );
  const pipeline = await device.createRenderPipelineAsync({
    label: 'Original folded ribbon',
    layout: 'auto',
    vertex: { module, entryPoint: 'vertexMain' },
    fragment: { module, entryPoint: 'fragmentMain', targets: [{ format }] },
    primitive: { topology: 'triangle-list', cullMode: 'none' },
    depthStencil: {
      format: 'depth24plus',
      depthWriteEnabled: true,
      depthCompare: 'less',
    },
    multisample: { count: 4 },
  });
  const renderBindings = device.createBindGroup({
    layout: pipeline.getBindGroupLayout(0),
    entries: [
      { binding: 0, resource: { buffer: camera } },
      { binding: 1, resource: { buffer: positions.gpuBuffer } },
      { binding: 2, resource: { buffer: normals.gpuBuffer } },
    ],
  });

  let destroyed = false,
    paused = false,
    visible = true;
  let frame = 0,
    previous = 0,
    time = 0,
    announced = false;
  let yaw = 0.32,
    pitch = 0.54,
    zoom = 1;
  let targetYaw = yaw,
    targetPitch = pitch;
  let pointerX = 0,
    pointerY = 0,
    pointerInside = false,
    dragging = false;
  let previousX = 0,
    previousY = 0;
  let lastInteraction = -Infinity;
  let motionOverride = false;
  let depth: GPUTexture | undefined, msaa: GPUTexture | undefined;
  let pixelW = 0,
    pixelH = 0;
  const cameraData = new Float32Array(24);
  const grid = { x: W, y: H };
  const zero = new Float32Array(N * 2);
  const abort = new AbortController();
  const signal = abort.signal;
  const oldTouchAction = canvas.style.touchAction;
  canvas.style.touchAction = 'pan-y';

  function resize() {
    const rect = canvas.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, 1.7);
    const width = Math.max(1, Math.round(rect.width * dpr));
    const height = Math.max(1, Math.round(rect.height * dpr));
    if (width === pixelW && height === pixelH) return;
    canvas.width = pixelW = width;
    canvas.height = pixelH = height;
    depth?.destroy();
    msaa?.destroy();
    depth = device.createTexture({
      size: [width, height],
      format: 'depth24plus',
      sampleCount: 4,
      usage: GPUTextureUsage.RENDER_ATTACHMENT,
    });
    msaa = device.createTexture({
      size: [width, height],
      format,
      sampleCount: 4,
      usage: GPUTextureUsage.RENDER_ATTACHMENT,
    });
  }
  function requestFrame() {
    if (!frame && !destroyed && visible) frame = requestAnimationFrame(draw);
  }
  function updatePointer(event: PointerEvent) {
    const rect = canvas.getBoundingClientRect();
    pointerX = ((event.clientX - rect.left) / Math.max(1, rect.width)) * 2 - 1;
    pointerY = 1 - ((event.clientY - rect.top) / Math.max(1, rect.height)) * 2;
    lastInteraction = performance.now();
    requestFrame();
  }
  canvas.addEventListener(
    'pointerenter',
    (event) => {
      pointerInside = true;
      updatePointer(event);
    },
    { signal },
  );
  canvas.addEventListener(
    'pointerleave',
    () => {
      pointerInside = false;
      requestFrame();
    },
    { signal },
  );
  canvas.addEventListener(
    'pointerdown',
    (event) => {
      if (event.button !== 0) return;
      dragging = true;
      pointerInside = true;
      previousX = event.clientX;
      previousY = event.clientY;
      canvas.setPointerCapture(event.pointerId);
      updatePointer(event);
    },
    { signal },
  );
  canvas.addEventListener(
    'pointermove',
    (event) => {
      if (dragging) {
        targetYaw -= (event.clientX - previousX) * 0.006;
        targetPitch = Math.max(
          -1.15,
          Math.min(1.15, targetPitch + (event.clientY - previousY) * 0.005),
        );
        previousX = event.clientX;
        previousY = event.clientY;
      }
      updatePointer(event);
    },
    { signal },
  );
  const stopDrag = () => {
    dragging = false;
    requestFrame();
  };
  canvas.addEventListener('pointerup', stopDrag, { signal });
  canvas.addEventListener('pointercancel', stopDrag, { signal });
  canvas.addEventListener('lostpointercapture', stopDrag, { signal });
  canvas.addEventListener(
    'keydown',
    (event) => {
      if (event.key === 'ArrowLeft') targetYaw -= 0.16;
      else if (event.key === 'ArrowRight') targetYaw += 0.16;
      else if (event.key === 'ArrowUp')
        targetPitch = Math.min(1.15, targetPitch + 0.12);
      else if (event.key === 'ArrowDown')
        targetPitch = Math.max(-1.15, targetPitch - 0.12);
      else if (event.key === '+' || event.key === '=')
        zoom = Math.max(0.78, zoom * 0.94);
      else if (event.key === '-') zoom = Math.min(1.4, zoom * 1.06);
      else if (event.key.toLowerCase() === 'r') {
        reset();
        return;
      } else return;
      event.preventDefault();
      lastInteraction = performance.now();
      requestFrame();
    },
    { signal },
  );
  document.addEventListener(
    'visibilitychange',
    () => {
      previous = 0;
      if (document.hidden) {
        if (frame) cancelAnimationFrame(frame);
        frame = 0;
      } else requestFrame();
    },
    { signal },
  );
  const resizeObserver = new ResizeObserver(() => requestFrame());
  resizeObserver.observe(canvas);
  const intersectionObserver = new IntersectionObserver((entries) => {
    visible = entries[0]?.isIntersecting ?? true;
    previous = 0;
    if (!visible) {
      if (frame) cancelAnimationFrame(frame);
      frame = 0;
    } else requestFrame();
  });
  intersectionObserver.observe(canvas);

  const onGPUError = (event: GPUUncapturedErrorEvent) => {
    event.preventDefault();
    paused = true;
    onStatus(`WebGPU error: ${event.error.message}`);
  };
  device.addEventListener('uncapturederror', onGPUError);
  ctx.lost.then((info) => {
    if (!destroyed) {
      paused = true;
      onStatus(`WebGPU device lost: ${info.message || info.reason}`);
    }
  });

  function draw(now: number) {
    frame = 0;
    if (destroyed || document.hidden || !visible) return;
    try {
      resize();
      const dt = previous ? Math.min((now - previous) / 1000, 0.025) : 1 / 60;
      previous = now;
      const interacting = dragging || now - lastInteraction < 1700;
      const running =
        !paused && (!options.reducedMotion || motionOverride || interacting);
      if (running) time += dt;
      if (running && !dragging && !pointerInside && !options.reducedMotion)
        targetYaw += dt * 0.045;
      const follow = options.reducedMotion ? 1 : 0.14;
      yaw += (targetYaw - yaw) * follow;
      pitch += (targetPitch - pitch) * follow;
      const aspect = pixelW / pixelH;
      const distance = (aspect < 1 ? 5.7 / Math.max(aspect, 0.64) : 5.5) * zoom;
      const eye: Vec3 = [
        Math.sin(yaw) * Math.cos(pitch) * distance,
        Math.sin(pitch) * distance,
        Math.cos(yaw) * Math.cos(pitch) * distance,
      ];
      const target: Vec3 = [0, 0.04, 0];
      const forward = normalize(sub(target, eye));
      const right = normalize(cross(forward, [0, 1, 0]));
      const up = cross(right, forward);
      const fov = Math.PI * 0.235;
      const tan = Math.tan(fov / 2);
      const direction = normalize([
        forward[0] + right[0] * pointerX * tan * aspect + up[0] * pointerY * tan,
        forward[1] + right[1] * pointerX * tan * aspect + up[1] * pointerY * tan,
        forward[2] + right[2] * pointerX * tan * aspect + up[2] * pointerY * tan,
      ]);
      cameraData.set(
        multiply(perspective(fov, aspect, 0.1, 30), lookAt(eye, target)),
        0,
      );
      cameraData.set([...eye, time, W, H, 0, 0], 16);
      device.queue.writeBuffer(camera, 0, cameraData);
      const encoder = device.createCommandEncoder({
        label: 'Ribbon: waves → geometry → normals → render',
      });
      propagate.encode(
        encoder,
        { next: wave.other.field, prev: wave.current.field, surface: positions },
        {
          grid,
          step: running ? dt * 60 : 0,
          origin: { x: eye[0], y: eye[1], z: eye[2] },
          ray: { x: direction[0], y: direction[1], z: direction[2] },
          pressure: pointerInside && interacting ? (dragging ? 0.007 : 0.0025) : 0,
        },
      );
      wave.swap();
      sculpt.encode(
        encoder,
        { surface: positions, field: wave.current.field },
        { grid, time },
      );
      deriveNormals.encode(encoder, { normal: normals, surface: positions }, { grid });
      const pass = encoder.beginRenderPass({
        colorAttachments: [
          {
            view: msaa!.createView(),
            resolveTarget: context!.getCurrentTexture().createView(),
            clearValue: { r: 0, g: 0, b: 0, a: 0 },
            loadOp: 'clear',
            storeOp: 'discard',
          },
        ],
        depthStencilAttachment: {
          view: depth!.createView(),
          depthClearValue: 1,
          depthLoadOp: 'clear',
          depthStoreOp: 'discard',
        },
      });
      pass.setPipeline(pipeline);
      pass.setBindGroup(0, renderBindings);
      pass.draw(N * 6);
      pass.end();
      device.queue.submit([encoder.finish()]);
      propagate.endSubmit();
      sculpt.endSubmit();
      deriveNormals.endSubmit();
      if (!announced) {
        announced = true;
        onStatus(`Live WebGPU · ${N.toLocaleString()} computed vertices`);
      }
      if (
        running ||
        Math.abs(targetYaw - yaw) > 0.0005 ||
        Math.abs(targetPitch - pitch) > 0.0005
      )
        requestFrame();
    } catch (error) {
      paused = true;
      propagate.endSubmit();
      sculpt.endSubmit();
      deriveNormals.endSubmit();
      onStatus(`WebGPU: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  function reset() {
    wave.current.field.write(zero);
    wave.other.field.write(zero);
    targetYaw = yaw = 0.32;
    targetPitch = pitch = 0.54;
    zoom = 1;
    time = 0;
    lastInteraction = performance.now();
    requestFrame();
  }
  requestFrame();
  return {
    destroy() {
      if (destroyed) return;
      destroyed = true;
      if (frame) cancelAnimationFrame(frame);
      abort.abort();
      resizeObserver.disconnect();
      intersectionObserver.disconnect();
      device.removeEventListener('uncapturederror', onGPUError);
      canvas.style.touchAction = oldTouchAction;
      depth?.destroy();
      msaa?.destroy();
      camera.destroy();
      propagate.destroy();
      sculpt.destroy();
      deriveNormals.destroy();
      positions.destroy();
      normals.destroy();
      wave.destroy();
    },
    setPaused(value: boolean) {
      paused = value;
      if (!value) motionOverride = true;
      previous = 0;
      requestFrame();
    },
    reset,
  };
}

type Vec3 = [number, number, number];
const sub = (a: Vec3, b: Vec3): Vec3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const dot = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a: Vec3, b: Vec3): Vec3 => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];
const normalize = (a: Vec3): Vec3 => {
  const l = Math.hypot(...a) || 1;
  return [a[0] / l, a[1] / l, a[2] / l];
};
function lookAt(eye: Vec3, target: Vec3) {
  const z = normalize(sub(eye, target)),
    x = normalize(cross([0, 1, 0], z)),
    y = cross(z, x);
  return new Float32Array([
    x[0],
    y[0],
    z[0],
    0,
    x[1],
    y[1],
    z[1],
    0,
    x[2],
    y[2],
    z[2],
    0,
    -dot(x, eye),
    -dot(y, eye),
    -dot(z, eye),
    1,
  ]);
}
function perspective(fovy: number, aspect: number, near: number, far: number) {
  const f = 1 / Math.tan(fovy / 2);
  return new Float32Array([
    f / aspect,
    0,
    0,
    0,
    0,
    f,
    0,
    0,
    0,
    0,
    far / (near - far),
    -1,
    0,
    0,
    (near * far) / (near - far),
    0,
  ]);
}
function multiply(a: Float32Array, b: Float32Array) {
  const out = new Float32Array(16);
  for (let column = 0; column < 4; column++)
    for (let row = 0; row < 4; row++) {
      out[column * 4 + row] =
        a[row] * b[column * 4] +
        a[4 + row] * b[column * 4 + 1] +
        a[8 + row] * b[column * 4 + 2] +
        a[12 + row] * b[column * 4 + 3];
    }
  return out;
}
